ate) maximo FROM gold.fato_pedidos x LEFT JOIN gold.dim_calendario c ON c.data_sk=x.data_entrega_sk UNION ALL SELECT 'fato_pedidos' fato,'order_estimated_delivery_date' papel,count(*) linhas,count(*) FILTER(WHERE x.order_estimated_delivery_date IS NULL) ausentes,count(*) FILTER(WHERE x.order_estimated_delivery_date IS NULL AND x.data_previsao_entrega_sk<>-1 OR x.order_estimated_delivery_date IS NOT NULL AND (c.dia IS DISTINCT FROM x.order_estimated_delivery_date::date)) divergencias,min(x.order_estimated_delivery_date) minimo,max(x.order_estimated_delivery_date) maximo FROM gold.fato_pedidos x LEFT JOIN gold.dim_calendario c ON c.data_sk=x.data_previsao_entrega_sk UNION ALL SELECT 'fato_itens_pedido' fato,'order_purchase_timestamp' papel,count(*) linhas,count(*) FILTER(WHERE x.order_purchase_timestamp IS NULL) ausentes,count(*) FILTER(WHERE x.order_purchase_timestamp IS NULL AND x.data_compra_sk<>-1 OR x.order_purchase_timestamp IS NOT NULL AND (c.dia IS DISTINCT FROM x.order_purchase_timestamp::date)) divergencias,min(x.order_purchase_timestamp) minimo,max(x.order_purchase_timestamp) maximo FROM gold.fato_itens_pedido x LEFT JOIN gold.dim_calendario c ON c.data_sk=x.data_compra_sk UNION ALL SELECT 'fato_itens_pedido' fato,'shipping_limit_date' papel,count(*) linhas,count(*) FILTER(WHERE x.shipping_limit_date IS NULL) ausentes,count(*) FILTER(WHERE x.shipping_limit_date IS NULL AND x.data_limite_envio_sk<>-1 OR x.shipping_limit_date IS NOT NULL AND (c.dia IS DISTINCT FROM x.shipping_limit_date::date)) divergencias,min(x.shipping_limit_date) minimo,max(x.shipping_limit_date) maximo FROM gold.fato_itens_pedido x LEFT JOIN gold.dim_calendario c ON c.data_sk=x.data_limite_envio_sk UNION ALL SELECT 'fato_pagamentos' fato,'order_purchase_timestamp' papel,count(*) linhas,count(*) FILTER(WHERE x.order_purchase_timestamp IS NULL) ausentes,count(*) FILTER(WHERE x.order_purchase_timestamp IS NULL AND x.data_compra_sk<>-1 OR x.order_purchase_timestamp IS NOT NULL AND (c.dia IS 